import { ObstacleType } from '../@types/obstacles.types';
import { ObstacleTypeUrlPart } from '../@types/obstacles.url.types';

export const getObstacleTypeFromUrl = (urlPart: ObstacleTypeUrlPart): ObstacleType => {
  const map: Record<ObstacleTypeUrlPart, ObstacleType> = {
    ['passes']: ObstacleType.Pass,
    ['peaks']: ObstacleType.Peak,
    ['poi']: ObstacleType.Poi,
  };
  return map[urlPart];
};

export const getUrlFromObstacleType = (type: ObstacleType): ObstacleTypeUrlPart => {
  const map: Record<ObstacleType, ObstacleTypeUrlPart> = {
    [ObstacleType.Pass]: 'passes',
    [ObstacleType.Peak]: 'peaks',
    [ObstacleType.Poi]: 'poi',
  };
  return map[type];
};
